import subprocess,re,uuid
def verify(monmap,expected):
    try:wanted=str(uuid.UUID(expected))
    except (ValueError,AttributeError,TypeError) as error:raise ValueError('literal expected UUID required') from error
    if uuid.UUID(wanted).int==0:raise ValueError('zero UUID does not identify an approved cluster')
    result=subprocess.run(['monmaptool','--print',monmap],capture_output=True,text=True,timeout=10)
    if result.returncode:raise RuntimeError('native monmap read failed')
    match=re.search(r'(?m)^fsid ([0-9a-fA-F-]{36})$',result.stdout+result.stderr)
    if not match:raise RuntimeError('native map FSID missing')
    actual=str(uuid.UUID(match[1]))
    if actual!=wanted:raise RuntimeError('map belongs to another cluster')
    return {'fsid':actual,'verified':True}
